const ease = [0.22, 1, 0.36, 1] as const;
const drawEase = [0.33, 0, 0.2, 1] as const;

type HeroLogoDrawProps = {
  className?: string;
};

export function HeroLogoDraw({ className }: HeroLogoDrawProps) {
  const reduce = useReducedMotion();

  if (reduce) {
    return (
      <svg
        className={cn("h-auto w-full text-fg", className)}
        viewBox="-12 -12 394 406"
        fill="none"
        xmlns="http://www.w3.org/2000/svg"
        role="img"
        aria-label="Thrun Design Co. mark"
      >
        <path d={MOUNTAIN_PATH} fill="#c59a53" />
        <path
          d={EMBLEM_PATH}
          fill="#f3f1eb"
          fillRule="evenodd"
          clipRule="evenodd"
        />
      </svg>
    );
  }

  return (
    <motion.div
      className={cn("relative w-full", className)}
      initial={{ opacity: 0, scale: 0.88, rotate: -2 }}
      animate={{ opacity: 1, scale: 1, rotate: 0 }}
      transition={{ duration: 0.9, ease }}
    >
      {/* Soft gold atmosphere — tonal depth, not neon */}
      <motion.div
        aria-hidden
        className="pointer-events-none absolute left-1/2 top-[42%] h-[78%] w-[90%] -translate-x-1/2 -translate-y-1/2"
        style={{
          background:
            "radial-gradient(ellipse at center, rgba(197,154,83,0.28) 0%, rgba(197,154,83,0.08) 42%, transparent 70%)",
        }}
        initial={{ opacity: 0, scale: 0.7 }}
        animate={{ opacity: 1, scale: 1 }}
        transition={{ duration: 1.4, delay: 0.15, ease }}
      />

      <motion.svg
        className="relative h-auto w-full overflow-visible"
        viewBox="-12 -12 394 406"
        fill="none"
        xmlns="http://www.w3.org/2000/svg"
        role="img"
        aria-label="Thrun Design Co. mark"
        initial={{ y: 20 }}
        animate={{ y: 0 }}
        transition={{ duration: 1.15, ease }}
      >
        {/* Mountain — bright leading stroke */}
        <motion.path
          d={MOUNTAIN_PATH}
          stroke="#e8c98a"
          strokeWidth={4}
          strokeLinecap="round"
          strokeLinejoin="round"
          fill="transparent"
          initial={{ pathLength: 0, opacity: 0.9 }}
          animate={{ pathLength: 1, opacity: [0.9, 0.9, 0] }}
          transition={{
            pathLength: { duration: 1.4, ease: drawEase, delay: 0.2 },
            opacity: { duration: 0.45, delay: 1.55, ease },
          }}
        />

        {/* Mountain — main gold stroke draw */}
        <motion.path
          d={MOUNTAIN_PATH}
          stroke="#c59a53"
          strokeWidth={2.2}
          strokeLinecap="round"
          strokeLinejoin="round"
          fill="#c59a53"
          initial={{ pathLength: 0, fillOpacity: 0, strokeOpacity: 1 }}
          animate={{
            pathLength: 1,
            fillOpacity: 1,
            strokeOpacity: 0,
          }}
          transition={{
            pathLength: { duration: 1.55, ease: drawEase, delay: 0.28 },
            fillOpacity: { duration: 0.55, ease, delay: 1.55 },
            strokeOpacity: { duration: 0.4, ease, delay: 1.85 },
          }}
        />

        {/* Emblem — soft under-stroke trail */}
        <motion.path
          d={EMBLEM_PATH}
          fillRule="evenodd"
          clipRule="evenodd"
          stroke="#c59a53"
          strokeWidth={3.2}
          strokeLinecap="round"
          strokeLinejoin="round"
          fill="transparent"
          initial={{ pathLength: 0, opacity: 0.35 }}
          animate={{ pathLength: 1, opacity: [0.35, 0.35, 0] }}
          transition={{
            pathLength: { duration: 2.55, ease: drawEase, delay: 0.95 },
            opacity: { duration: 0.5, delay: 3.2, ease },
          }}
        />

        {/* Emblem — crisp gold draw, then cream fill */}
        <motion.path
          d={EMBLEM_PATH}
          fillRule="evenodd"
          clipRule="evenodd"
          stroke="#c59a53"
          strokeWidth={1.35}
          strokeLinecap="round"
          strokeLinejoin="round"
          fill="#f3f1eb"
          initial={{ pathLength: 0, fillOpacity: 0, strokeOpacity: 1 }}
          animate={{
            pathLength: 1,
            fillOpacity: 1,
            strokeOpacity: 0,
          }}
          transition={{
            pathLength: { duration: 2.55, ease: drawEase, delay: 1.05 },
            fillOpacity: { duration: 0.75, ease, delay: 3.15 },
            strokeOpacity: { duration: 0.45, ease, delay: 3.5 },
          }}
        />

        {/* Peak settle — lands when mountain finishes drawing */}
        <motion.circle
          cx="184.869"
          cy="6"
          r="4"
          fill="#e8c98a"
          initial={{ scale: 0, opacity: 0 }}
          animate={{ scale: [0, 1.85, 1], opacity: [0, 1, 0.85] }}
          transition={{ duration: 0.75, delay: 1.5, ease }}
        />
        <motion.circle
          cx="184.869"
          cy="6"
          r="10"
          fill="none"
          stroke="#c59a53"
          strokeWidth={1}
          initial={{ scale: 0.2, opacity: 0 }}
          animate={{ scale: [0.2, 1.8], opacity: [0.7, 0] }}
          transition={{ duration: 0.9, delay: 1.52, ease }}
        />
      </motion.svg>
    </motion.div>
  );
}
